-- Spending, own revenue and pending bills for all 47 counties, read from the Controller of Budget's annual County
-- Governments Budget Implementation Review Reports, and audit opinions from the Auditor-General's county reports.
-- Figures are in shillings, converted from the reports' tables; every row was checked against the table's own totals
-- (target = ordinary + health-fund parts, total = recurrent + development). Load into any county's project: it is national data.
-- Safe to run again: rows are replaced by county and year.

on conflict (county_code, fiscal_year) do update set dev_budget = excluded.dev_budget, dev_spent = excluded.dev_spent,
  rec_budget = excluded.rec_budget, rec_spent = excluded.rec_spent, osr_target = excluded.osr_target, osr_actual = excluded.osr_actual,
  pending_bills = excluded.pending_bills, audit_opinion = excluded.audit_opinion, source = excluded.source, source_url = excluded.source_url, updated_at = now();
